function countGoodSubsequences(s) {
  const MOD = 1000000007n;
  const n = s.length;
  const counts = new Array(26).fill(0);
  for (const ch of s) {
    counts[ch.charCodeAt(0) - 97]++;
  }

  const power = (base, exp) => {
    let result = 1n;
    while (exp > 0n) {
      if (exp & 1n) result = (result * base) % MOD;
      base = (base * base) % MOD;
      exp >>= 1n;
    }
    return result;
  };
  const fact = new Array(n + 1).fill(1n);
  for (let i = 1; i <= n; i++) {
    fact[i] = (fact[i - 1] * BigInt(i)) % MOD;
  }
  const invFact = new Array(n + 1).fill(1n);
  invFact[n] = power(fact[n], MOD - 2n);
  for (let i = n; i > 0; i--) {
    invFact[i - 1] = (invFact[i] * BigInt(i)) % MOD;
  }
  const choose = (total, pick) => (((fact[total] * invFact[pick]) % MOD) * invFact[total - pick]) % MOD;

  const maxCount = Math.max(...counts);
  let answer = 0n;
  for (let freq = 1; freq <= maxCount; freq++) {
    let ways = 1n;
    for (const count of counts) {
      if (count >= freq) {
        ways = (ways * (choose(count, freq) + 1n)) % MOD;
      }
    }
    answer = (answer + ways - 1n + MOD) % MOD;
  }
  return Number(answer);
}

