function countGoodSubsequences(s) {
  // Try every non-empty set of positions and check the letter frequencies directly.
  const n = s.length;
  let total = 0;
  for (let mask = 1; mask < (1 << n); mask++) {
    const freq = new Map();
    for (let i = 0; i < n; i++) if (mask & (1 << i)) freq.set(s[i], (freq.get(s[i]) || 0) + 1);
    const values = [...freq.values()];
    if (values.every(v => v === values[0])) total++;
  }
  return total % 1000000007;
}

