function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  if (size === 'large') {
    const n = 10000;
    // Few letters make long runs of one frequency; all 26 spread the counts out.
    const shape = rand();
    const width = shape < 0.2 ? 1 : shape < 0.5 ? 1 + Math.floor(rand() * 4) : 26;
    return [Array.from({ length: n }, () => letters[Math.floor(rand() * width)]).join('')];
  }
  const n = 1 + Math.floor(rand() * 12);
  const width = 1 + Math.floor(rand() * 4);
  const offset = Math.floor(rand() * (26 - width + 1));
  return [Array.from({ length: n }, () => letters[offset + Math.floor(rand() * width)]).join('')];
}
